WHERE project_id=#{projectId}
AND name LIKE CONCAT('%',#{query.keyword},'%')
AND status=#{query.status}
AND target_role=#{query.targetRole}

WHERE project_id=#{projectId}
AND assignee_user_id=#{assigneeId}
AND status=#{query.status}
AND path_id=#{query.pathId}
AND due_at <=#{query.dueBefore}
